(() => {
 const el=id=>document.getElementById(id),labels={login:'Inicio de sesión (todos los portales)',prequalification:'Precalificación de crédito',freelance:'Solicitud de ingreso Freelance',chat:'Consultas al asistente',referral:'Registro de referido',credit:'Solicitud de crédito Freelance',finalize:'Formulario de finalización Freelance'};
 let config=null;
 const status=(text,error=false)=>{el('status').textContent=text;el('status').classList.toggle('error',error)};
 async function api(path,body){const response=await fetch('/api/security/admin/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const result=await response.json().catch(()=>({}));if(!response.ok)throw Error(result.error||'No se pudo contactar al servidor de seguridad.');return result;}
 function paint(value){config=value;el('securityLogin').hidden=true;el('securityConfig').hidden=false;el('enabled').checked=value.enabled;el('siteKey').value=value.siteKey;el('secretKey').value='';el('hostnames').value=value.hostnames.join('\n');el('secretState').textContent=value.secretConfigured?'Hay una clave secreta configurada. Déjala vacía para conservarla.':'Todavía no hay clave secreta.';el('securityState').textContent=value.enabled?'Protección activada':'Protección desactivada';el('formChoices').replaceChildren();for(const [key,text]of Object.entries(labels)){const label=document.createElement('label');label.className='check';const input=document.createElement('input');input.type='checkbox';input.checked=value.forms[key]!==false;input.dataset.form=key;label.append(input,document.createTextNode(text));el('formChoices').append(label)}}
 async function refresh(){paint(await api('config'));}
 el('securityLogin').onsubmit=async event=>{event.preventDefault();try{await api('login',{password:el('securityPassword').value});el('securityPassword').value='';await refresh();status('Sesión administrativa iniciada.')}catch(error){status(error.message,true)}};
 el('securityConfig').onsubmit=async event=>{event.preventDefault();const payload={enabled:el('enabled').checked,siteKey:el('siteKey').value,secretKey:el('secretKey').value,hostnames:el('hostnames').value.split(/[\s,]+/).filter(Boolean),forms:Object.fromEntries([...document.querySelectorAll('[data-form]')].map(input=>[input.dataset.form,input.checked]))};try{paint(await api('config',payload));status('Configuración guardada en el servidor. Se aplicará a todos los visitantes.');if(parent!==window)parent.postMessage({type:'tvs-captcha-config-saved'},location.origin)}catch(error){status(error.message,true)}};
 el('refreshConfig').onclick=()=>refresh().catch(error=>status(error.message,true));
 el('securityLogout').onclick=async()=>{try{await api('logout',{});el('securityConfig').hidden=true;el('securityLogin').hidden=false;status('Sesión de seguridad cerrada.')}catch(error){status(error.message,true)}};
 refresh().catch(()=>{status('Ingresa para administrar las claves. El servidor debe estar en ejecución.');});
})();
